package solution

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"errors"
	"testing"
)

func signTestPayload(payload, key []byte) string {
	payloadPart := base64.RawURLEncoding.EncodeToString(payload)
	mac := hmac.New(sha256.New, key)
	_, _ = mac.Write([]byte(payloadPart))
	return payloadPart + "." + base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
}

func TestPassServiceIssueIsDeterministicAndVerifyRoundTrips(t *testing.T) {
	service, err := NewPassService("secret-key")
	if err != nil {
		t.Fatalf("NewPassService returned error: %v", err)
	}
	claims := PassClaims{Subject: "user-7", DisplayName: "Ada", ExpiresAt: 100}
	token, err := service.Issue(claims)
	if err != nil {
		t.Fatalf("Issue returned error: %v", err)
	}
	wantToken := signTestPayload([]byte(`{"sub":"user-7","name":"Ada","exp":100}`), []byte("secret-key"))
	if token != wantToken {
		t.Fatalf("Issue() = %q, want %q", token, wantToken)
	}
	got, err := service.Verify(token, 99)
	if err != nil {
		t.Fatalf("Verify returned error: %v", err)
	}
	if got != claims {
		t.Fatalf("Verify() = %#v, want %#v", got, claims)
	}
}

func TestPassServiceExpirationBoundary(t *testing.T) {
	service, _ := NewPassService("key")
	token, err := service.Issue(PassClaims{Subject: "s", ExpiresAt: 5})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := service.Verify(token, 4); err != nil {
		t.Fatalf("token rejected before expiration: %v", err)
	}
	if got, err := service.Verify(token, 5); err == nil || got != (PassClaims{}) {
		t.Fatalf("expiration boundary returned (%#v, %v), want zero claims and error", got, err)
	}
}

func TestPassServiceRejectsInvalidConstructionAndClaims(t *testing.T) {
	if service, err := NewPassService(""); err == nil || service != nil {
		t.Fatalf("empty key returned (%#v, %v), want nil and error", service, err)
	}
	service, _ := NewPassService("key")
	invalid := []PassClaims{
		{Subject: "", ExpiresAt: 1},
		{Subject: "s", ExpiresAt: 0},
		{Subject: "s", ExpiresAt: -1},
	}
	for _, claims := range invalid {
		if token, err := service.Issue(claims); err == nil || token != "" {
			t.Errorf("Issue(%#v) returned (%q, %v), want empty token and error", claims, token, err)
		}
	}
}

func TestPassServiceVerifyRejectsMalformedAndInvalidTokens(t *testing.T) {
	service, _ := NewPassService("key")
	valid, _ := service.Issue(PassClaims{Subject: "s", DisplayName: "n", ExpiresAt: 20})
	wrongKeyToken := signTestPayload([]byte(`{"sub":"s","name":"n","exp":20}`), []byte("other"))

	cases := []struct {
		name  string
		token string
		at    int64
	}{
		{"negative time", valid, -1},
		{"empty token", "", 0},
		{"one part", "abc", 0},
		{"three parts", "a.b.c", 0},
		{"invalid payload encoding", "*.AA", 0},
		{"invalid signature encoding", "AA.*", 0},
		{"wrong signature", wrongKeyToken, 0},
		{"malformed JSON", signTestPayload([]byte(`{"sub":`), []byte("key")), 0},
		{"trailing JSON", signTestPayload([]byte(`{"sub":"s","name":"n","exp":20} {}`), []byte("key")), 0},
		{"empty subject", signTestPayload([]byte(`{"sub":"","name":"n","exp":20}`), []byte("key")), 0},
		{"zero expiration", signTestPayload([]byte(`{"sub":"s","name":"n","exp":0}`), []byte("key")), 0},
		{"negative expiration", signTestPayload([]byte(`{"sub":"s","name":"n","exp":-2}`), []byte("key")), 0},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, err := service.Verify(tc.token, tc.at)
			if err == nil {
				t.Fatalf("Verify unexpectedly succeeded with %#v", got)
			}
			if got != (PassClaims{}) {
				t.Fatalf("failed verification returned claims %#v", got)
			}
		})
	}

	if errors.Is(nil, errors.New("unreachable")) {
		t.Fatal("unreachable")
	}
}

package solution

import "testing"

func TestReviewTokenEncoding0160(t *testing.T) {
	s, err := NewPassService("review-key")
	if err != nil { t.Fatal(err) }
	token, err := s.Issue(PassClaims{Subject:"s",DisplayName:"n",ExpiresAt:10})
	if err != nil { t.Fatal(err) }
	if _, err = s.Verify(token, 0); err != nil { t.Fatal(err) }
	if claims, err := s.Verify(token+"\n", 0); err == nil {
		t.Fatalf("non-base64url newline accepted: %+v", claims)
	}
}

